Lang["Q1_7848"] = "Harmonização com o Núcleo"
Lang["Q2_7848"] = "Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo."
Lang["Q1_4903"] = "O comando do Senhor da Guerra"
Lang["Q2_4903"] = "Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida."
Lang["Q1_4941"] = "A sabedoria de Eitrigg"
Lang["Q2_4941"] = "Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall.\n\nVocê se lembra de ter visto Eitrigg nos aposentos de Thrall."
Lang["Q1_4974"] = "Pela Horda!"
Lang["Q2_4974"] = "Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar."
Lang["Q1_6566"] = "O que o vento carrega"
Lang["Q2_6566"] = "Ouça Thrall."
Lang["Q1_6567"] = "O campeão da Horda"
Lang["Q2_6567"] = "Procure Rexxar. O Chefe Guerreiro <o/a> instruiu quanto ao paradeiro dele. Procure nos caminhos de Desolação, entre a Cordilheira das Torres de Pedra e Feralas."
Lang["Q1_6568"] = "O testamento de Rexxar"
Lang["Q2_6568"] = "Leve o Testamento de Rexxar para Myranda, a Bruxa Velha, nas Terras Pestilentas Ocidentais."
Lang["Q1_6569"] = "Ilusões ópticas"
Lang["Q2_6569"] = "Vá para o Pico da Rocha Negra e colete 20 Olhos de Dragomorfo Preto. Fale novamente com Myranda, a Bruxa Velha, depois que tiver terminado a tarefa."
Lang["Q1_6570"] = "Ardeluta"
Lang["Q2_6570"] = "Vá até o Pântano da Serpe, no Pântano Vadeoso, e procure o Covil de Ardeluta. Quando estiver lá, use o Amuleto de Subversão Dracônica e fale com Ardeluta."
Lang["Q1_6584"] = "O teste dos crânios: Chronalis"
Lang["Q2_6584"] = "Guardando as Cavernas do Tempo no Deserto de Tanaris, encontra-se Chronalis, filho de Nozdormu. Destrua-o e leve seu crânio para Ardeluta."
Lang["Q1_6582"] = "O teste dos crânios: Áugure"
Lang["Q2_6582"] = "Encontre e mate o Áugure, o draco da Revoada Dragônica Azul. Arranque a cabeça do draco morto e leve-a para Ardeluta.\n\nVocê sabe que o Áugure se encontra em Hibérnia."
Lang["Q1_6583"] = "O teste dos crânios: Somnus"
Lang["Q2_6583"] = "Destrua Somnus, o draco campeão da Revoada Verde. Pegue seu crânio e leve-o para Ardeluta."
Lang["Q1_6585"] = "O teste dos crânios: Axtroz"
Lang["Q2_6585"] = "Vá para Grim Batol e encontre Axtroz, o draco campeão da Revoada Vermelha. Destrua-o e arranque sua cabeça. Leve o crânio para Ardeluta."
Lang["Q1_6601"] = "Ascensão..."
Lang["Q2_6601"] = "Pelo jeito, a farsa chegou ao fim. Você já sabe que o Amuleto de Subversão Dracônica criado por Myranda, a Bruxa Velha, não vai funcionar no Pico da Rocha Negra. Você devia ir atrás de Rexxar e explicar a situação. Mostre a ele o Amuleto da Chama Dracônica Fraco. Pode ser que ele saiba o que fazer."
Lang["Q1_6602"] = "Sangue do Campeão dos Dragões Negros"
Lang["Q2_6602"] = "Viaje para o Pico da Rocha Negra e mate o General Drakkisath. Recolha seu sangue e leve-o para Rexxar."
Lang["Q1_4182"] = "Ameaça draconiana"
Lang["Q2_4182"] = "Mate 15 Filhotes Negros, 10 Dragomorfos Negros, 4 Draconoides Negros e 1 Draco Negro. Fale novamente com Helendis Flumicórnio quando a tarefa estiver concluída."
Lang["Q1_4183"] = "Os verdadeiros mestres"
Lang["Q2_4183"] = "Viaje até Vila Plácida e entregue a Carta de Helendis Flumicórnio ao Magistrado Salomão."
Lang["Q1_4184"] = "Os verdadeiros mestres"
Lang["Q2_4184"] = "Viaje para Ventobravo e entregue o Apelo de Salomão ao Grão-lorde Bolvar Fordragon.\n\nBolvar reside na Bastilha Ventobravo."
Lang["Q1_4185"] = "Os verdadeiros mestres"
Lang["Q2_4185"] = "Fale com o Grão-lorde Bolvar Fordragon depois de falar com a Lady Katrana Prestor."
Lang["Q1_4186"] = "Os verdadeiros mestres"
Lang["Q2_4186"] = "Leve o Decreto de Bolvar para o Magistrado Salomão, em Vila Plácida."
Lang["Q1_4223"] = "Os verdadeiros mestres"
Lang["Q2_4223"] = "Fale com o Oficial Maxwell nas Estepes Ardentes."
Lang["Q1_4224"] = "Os verdadeiros mestres"
Lang["Q2_4224"] = "Fale com João Roto para saber o destino do Marechal Vilasboas e fale novamente com o Oficial Maxwell quando tiver completado essa tarefa.\n\nVocê se lembra do Oficial Maxwell lhe dizendo para procurá-lo em uma caverna ao norte."
Lang["Q1_4241"] = "Marechal Vilasboas"
Lang["Q2_4241"] = "Viaje para a Montanha Rocha Negra, a noroeste, e entre no Abismo Rocha Negra. Descubra o que aconteceu com o Marechal Vilasboas.\n\nVocê se lembra de João Roto falando sobre Vilasboas ter sido arrastado para uma prisão."
Lang["Q1_4242"] = "Esperança abandonada"
Lang["Q2_4242"] = "Leve as más notícias ao Oficial Maxwell."
Lang["Q1_4264"] = "Bilhete amassado"
Lang["Q2_4264"] = "Você pode ter acabado de descobrir algo que o Marechal Vilasboas estaria interessado em ver. Pode haver esperança, afinal."
Lang["Q1_4282"] = "Um fiapo de esperança"
Lang["Q2_4282"] = "Recupere as Informações Perdidas do Marechal Vilasboas.\n\nO Marechal Vilasboas acredita que as informações estão sendo mantidas pelo Lorde Golem Argelmach e pelo General Forjaversa."
Lang["Q1_4322"] = "Fuga da prisão!"
Lang["Q2_4322"] = "Ajude o Marechal Vilasboas a recuperar seu equipamento e libertar seus amigos. Se conseguir, fale novamente com o Oficial Maxwell."
Lang["Q1_6402"] = "Encontro marcado em Ventobravo"
Lang["Q2_6402"] = "Viaje a Ventobravo e vá até os portões da cidade. Fale com o Escudeiro Rui para que ele avise ao Marechal Vilasboas que você chegou."
Lang["Q1_6403"] = "O grande baile de máscaras"
Lang["Q2_6403"] = "Siga Reginaldo Vilasboas através de Ventobravo. Proteja-o de qualquer ataque!"
Lang["Q1_6501"] = "O Olho do Dragão"
Lang["Q2_6501"] = "Você deve vasculhar o mundo em busca de uma criatura capaz de restaurar o poder do Fragmento do Olho do dragão. A única informação que você tem sobre essa criatura é que ela existe."
Lang["Q1_6502"] = "Amuleto da Chama Dracônica"
Lang["Q2_6502"] = "Confronte o General Drakkisath e consiga o Sangue do Campeão dos Dragões Negros. Drakkisath está na sala do trono atrás dos Salões da Ascensão, no Pico da Rocha Negra."
Lang["Q1_7761"] = "Comando do Mão Negra"
Lang["Q2_7761"] = "Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath.\n\nA carta indica que o próprio General Drakkisath a guarda. Talvez você devesse investigar."
Lang["Q1_9121"] = "A cidadela medonha: Naxxramas"
Lang["Q2_9121"] = "A Arquimaga Ângela Santoro, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais, quer 5 Cristais Arcanos, 2 Cristais do Nexus, 1 Orbe da Retidão e 60 peças de ouro. Você tem que ser Honrad<o/a> pela Aurora Argêntea."
Lang["Q1_9122"] = "A cidadela medonha: Naxxramas"
Lang["Q2_9122"] = "A Arquimaga Ângela Santoro, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais, quer 2 Cristais Arcanos, 1 Cristal do Nexus e 30 peças de ouro. Você tem que ser Reverenciad<o/a> pela Aurora Argêntea."
Lang["Q1_9123"] = "A cidadela medonha: Naxxramas"
Lang["Q2_9123"] = "A Arquimaga Ângela Santoro, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais, dará a você a Ocultação Arcana sem nenhum custo. Você tem que ser Exaltad<o/a> pela Aurora Argêntea."
Lang["Q1_8286"] = "O que nos traz o dia de amanhã"
Lang["Q2_8286"] = "Adentre as Cavernas do Tempo, em Tanaris, e encontre Anacronos, Prole de Nozdormu."
Lang["Q1_8288"] = "Só pode ascender um"
Lang["Q2_8288"] = "Leve a Cabeça do Prolemestre Flagelador para Baristolth das Areias Cambiantes no Forte Cenariano, em Silithus."
Lang["Q1_8301"] = "O caminho do íntegros"
Lang["Q2_8301"] = "Colete 200 Fragmentos de Carapaça Silitídea e fale novamente com Baristolth."
Lang["Q1_8303"] = "Anacronos"
Lang["Q2_8303"] = "Encontre Anacronos nas Cavernas do Tempo, em Tanaris."
Lang["Q1_8305"] = "Relembranças longínquas"
Lang["Q2_8305"] = "Localize a Lágrima Cristalina em Silithus, e contemple suas profundezas."
Lang["Q1_8519"] = "Um peão no tabuleiro eterno"
Lang["Q2_8519"] = "Aprenda tudo que puder sobre o passado, depois fale com Anacronos nas Cavernas do Tempo, em Tanaris."
Lang["Q1_8555"] = "O ataque das revoadas"
Lang["Q2_8555"] = "Eranikus, Vaelastrasz e Azuregos... Sem dúvida você conhece esses dragões, mortal. Não é coincidência que tenham tido papéis tão importantes como vigias do nosso mundo.\n\nInfelizmente (e minha própria ingenuidade tem parte da culpa), seja por agentes dos Deuses Antigos, seja por traição de quem os chamava de amigos, cada guardião caiu em tragédia. Isso alimentou minha desconfiança da sua espécie.\n\nProcure-os... E prepare-se para o pior."
Lang["Q1_8730"] = "A corrupção de Nefarius"
Lang["Q2_8730"] = "Mate Nefarian e recupere o Estilhaço de Cetro Vermelho. Devolva o Estilhaço de Cetro Vermelho a Anacronos nas Cavernas do Tempo, em Tanaris. Você tem 5 horas para concluir a tarefa."
Lang["Q1_8733"] = "Erânicos, Tirano dos Sonhos"
Lang["Q2_8733"] = "Vá para o continente de Teldrassil e encontre o agente de Malfurion perto das muralhas de Darnassus."
Lang["Q1_8734"] = "Tyrande e Remulos"
Lang["Q2_8734"] = "Vá à Clareira da Lua e fale com o Guardião Remulos."
Lang["Q1_8735"] = "A Corrupção do Pesadelo"
Lang["Q2_8735"] = "Vá até os quatro portais do Sonho Esmeralda em Azeroth e obtenha um Fragmento da Corrupção do Pesadelo de cada um. Quando tiver cumprido essa tarefa, fale novamente com o Guardião Remulos na Clareira da Lua."
Lang["Q1_8736"] = "Os pesadelos manifestos"
Lang["Q2_8736"] = "Defenda o Refúgio Noturno de Erânicos. Impeça que o Guardião Remulos pereça. Não mate Erânicos. Defenda-se. Espere Tyrande."
Lang["Q1_8741"] = "O campeão está de volta"
Lang["Q2_8741"] = "Leve o Estilhaço de Cetro Verde a Anacronos, que está nas Cavernas do Tempo, em Tanaris."
Lang["Q1_8575"] = "O livro-caixa mágico de Azuregos"
Lang["Q2_8575"] = "Entregue o Livro-caixa Mágico de Azuregos a Narain Suavestilo em Tanaris."
Lang["Q1_8576"] = "Traduzindo o livro"
Lang["Q2_8576"] = "Primeiro o mais importante! Precisamos descobrir o que Azuregos escreveu neste livro-razão.\n\nVocê diz que ele mandou fazer uma boia de arcanita e que este é o diagrama? Estranho ele escrever em dracônico. Aquele velho sabe que eu não leio essa bobagem.\n\nPara isso funcionar, vou precisar dos meus óculos de vidência, de uma galinha de duzentos quilos e do volume II de 'Dracônico para Leigos'. Não necessariamente nessa ordem."
Lang["Q1_8597"] = "Dracônico para Leigos"
Lang["Q2_8597"] = "Encontre o livro de Narain Suavestilo, enterrado em uma ilha nos Mares do Sul."
Lang["Q1_8599"] = "Canção de amor para Narain"
Lang["Q2_8599"] = "Entregue a Carta de Amor de Meridith a Narain Suavestilo em Tanaris."
Lang["Q1_8598"] = "r3sGAte"
Lang["Q2_8598"] = "Leve o Pedido de Resgate a Narain Suavestilo em Tanaris."
Lang["Q1_8606"] = "Isca!"
Lang["Q2_8606"] = "Narain Suavestilo, em Tanaris, quer que você vá a Hibérnia e coloque o saco de ouro no ponto determinado pelos sequestradores do livro."
Lang["Q1_8620"] = "A única prescrição"
Lang["Q2_8620"] = "Recupere os 8 Capítulos Perdidos de Dracônico para Leigos, combine-os com a Capa Mágica de Livros e entregue o exemplar restaurado de Dracônico para Leigos: Volume II para Narain Suavestilo, em Tanaris."
Lang["Q1_8584"] = "Nunca questione o meu trabalho"
Lang["Q2_8584"] = "Narain Suavestilo, em Tanaris, quer que você fale com Funesto Marrão em Geringontzan."
Lang["Q1_8585"] = "A Ilha do Medo!"
Lang["Q2_8585"] = "Obtenha a Carcaça de Lakmaeran e 20 Lombos de Quiméroco para Funesto Marrão em Tanaris."
Lang["Q1_8586"] = "As costeletas sinistronas de quiméroco do Funesto"
Lang["Q2_8586"] = "Funesto Marrão, em Geringontzan, quer que você providencie 20 unidades de Combustível de Foguete Goblínico e 20 de Sal Rochafunda."
Lang["Q1_8587"] = "De volta a Narain"
Lang["Q2_8587"] = "Entregue o Frango de 250 Quilos a Narain Suavestilo em Tanaris."
Lang["Q1_8577"] = "Stewvul, o ex-melhor amigo no mundo todo"
Lang["Q2_8577"] = "Narain Suavestilo quer que você localize o ex-melhor amigo dele no mundo inteiro, Stewvul, e recupere os óculos de vidência que Stewvul lhe roubou."
Lang["Q1_8578"] = "Óculos de vidência? Sem problema!"
Lang["Q2_8578"] = "Encontre os Óculos da Vidência de Narain e devolva-os para Narain Suavestilo em Tanaris."
Lang["Q1_8728"] = "As boas e más notícias"
Lang["Q2_8728"] = "Narain Suavestilo, em Tanaris, quer que você leve para ele 20 Barras de Arcanita, 10 Minérios de Elemêntio, 10 Diamantes Azerotianos e 10 Safiras Azuis."
Lang["Q1_8729"] = "A ira de Neptulon"
Lang["Q2_8729"] = "Use a Boia de Arcanita na Voragem Serpenteante da Baía das Tempestades, que fica em Azshara."
Lang["Q1_8742"] = "O poder de Kalimdor"
Lang["Q2_8742"] = "Mil anos se passaram e, como estava destinado, alguém está diante de mim. Alguém que levará seu povo a uma nova era.\n\nO Deus Antigo treme. Ah, sim, ele teme a sua fé. Destrua a profecia de C'Thun.\n\nEle sabe que você vem, campeão, e com você vem o poder de Kalimdor. Basta me avisar quando estiver pronto e eu lhe darei o Cetro das Areias Movediças."
Lang["Q1_8745"] = "O tesouro do Atemporal"
Lang["Q2_8745"] = "Saudações, campeão. Sou Jonathan, guardião do gongo sagrado e vigia eterno da Revoada Bronze.\n\nO próprio Atemporal me deu o poder de lhe conceder um item à sua escolha do tesouro dele. Que ele o ajude nas batalhas contra C'Thun."
Lang["Q1_10755"] = "Entre na Cidadela"
Lang["Q2_10755"] = "Entregue o Molde Pronto de Chave a Nazgrel de Thrallmar, na Península Fogo do Inferno."
Lang["Q1_10756"] = "Grão-mestre Rohok"
Lang["Q2_10756"] = "Leve o Molde Pronto de Chave para Rohok em Thrallmar."
Lang["Q1_10757"] = "O pedido de Rohok"
Lang["Q2_10757"] = "Leve 4 Barras de Ferrovil, 2 amostras de Pó Arcano e 4 Partículas de Fogo para Rohok, em Thrallmar, na Península Fogo do Inferno."
Lang["Q1_10758"] = "Mais quente que o inferno"
Lang["Q2_10758"] = "Destrua um Aníquilus na Península Fogo do Inferno e jogue o Molde não Aquecido de Chave nos destroços. Leve o Molde Queimado de Chave para Rohok, em Thrallmar."
Lang["Q1_10754"] = "Entre na Cidadela"
Lang["Q2_10754"] = "Leve o Molde Pronto de Chave ao Comandante-chefe Danath Matatroll na Fortaleza da Honra, que fica na Península Fogo do Inferno."
Lang["Q1_10762"] = "Grão-Mestre Rumberto"
Lang["Q2_10762"] = "Leve o Molde Pronto de Chave para Rumberto na Fortaleza da Honra."
Lang["Q1_10763"] = "O pedido de Rumberto"
Lang["Q2_10763"] = "Leve 4 Barras de Ferrovil, 2 montinhos de Pó Arcano e 4 Partículas de Fogo para Rumberto, na Fortaleza da Honra, que fica na Península Fogo do Inferno."
Lang["Q1_10764"] = "Mais quente que o inferno"
Lang["Q2_10764"] = "Destrua um Aníquilus na Península Fogo do Inferno e jogue o Molde não Aquecido de Chave nos destroços. Leve o Molde Queimado de Chave para Rumberto na Fortaleza da Honra."
Lang["Q1_10279"] = "Para o covil do mestre"
Lang["Q2_10279"] = "Fale com Andormu nas Cavernas do Tempo."
Lang["Q1_10277"] = "Cavernas do Tempo"
Lang["Q2_10277"] = "Andormu, nas Cavernas do Tempo, lhe conferiu a tarefa de seguir a Guia do Tempo pela caverna."
Lang["Q1_10282"] = "Antiga Eira dos Montes"
Lang["Q2_10282"] = "Andormu, nas Cavernas do Tempo, lhe conferiu a tarefa de ir até a Antiga Eira dos Montes e falar com Erozion."
Lang["Q1_10283"] = "Distração de Taretha"
Lang["Q2_10283"] = "Vá ao Forte do Desterro e prepare 5 cargas incendiárias nos barris encontrados dentro dos campos de prisioneiros, usando a Carga de Bombas Incendiárias que Erozion lhe deu.\n\nFale com Thrall na prisão do porão do Forte do Desterro quando tiver incendiado os alojamentos."
Lang["Q1_10284"] = "A fuga do Forte do Desterro"
Lang["Q2_10284"] = "Quando estiver <pronto/pronta> para continuar, avise Thrall. Siga-o e ajude-o a libertar Taretha e a cumprir o destino dele.\n\nFale com Erozion na Antiga Eira dos Montes caso tenha sucesso nesta missão."
Lang["Q1_10285"] = "Reencontro com Andormu"
Lang["Q2_10285"] = "Fale novamente com a criança Andormu nas Cavernas do Tempo, que ficam no deserto de Tanaris."
Lang["Q1_10265"] = "Coleta de cristais para o Consórcio"
Lang["Q2_10265"] = "Obtenha o artefato de cristal de Arklon e leve-o ao Espreitador Etéreo Khay'ji, na Área 52, em Eternévoa."
Lang["Q1_10262"] = "Destroços etéreos"
Lang["Q2_10262"] = "Colete 10 Insígnias Zaxxis e leve-as ao Espreitador Etéreo Khay'ji, na Área 52, em Eternévoa."
Lang["Q1_10205"] = "Saqueador Dimensional Nesaad"
Lang["Q2_10205"] = "Mate o Saqueador Dimensional Nesaad e fale novamente com o Espreitador Etéreo Khay'ji, na Área 52, em Eternévoa."
Lang["Q1_10266"] = "Pedido de assistência"
Lang["Q2_10266"] = "Procure-o e ofereça-lhe os seus serviços. Ele se encontra no Posto Terramédia, dentro do Eco-domo Terramédia, em Eternévoa."
Lang["Q1_10267"] = "Retomada justa"
Lang["Q2_10267"] = "Colete 10 Caixas de Equipamento de Sondagem e leve-os a Gahruj, no Posto Terramédia, dentro do Eco-domo Terramédia, em Eternévoa."
Lang["Q1_10268"] = "Audiência com o príncipe"
Lang["Q2_10268"] = "Entregue o Equipamento de Sondagem à imagem do Príncipe do Nexus Haramad, no Pináculo da Tempestade, em Eternévoa."
Lang["Q1_10269"] = "Ponto de triangulação um"
Lang["Q2_10269"] = "Use o Dispositivo de Triangulação para indicar a direção do primeiro ponto de triangulação. Assim que o encontrar, relate sua localização ao Mercador Hazzin, na Guarita do Protetorado, na ilha de Manaforja Ultris, em Eternévoa."
Lang["Q1_10275"] = "Ponto de triangulação dois"
Lang["Q2_10275"] = "Use o Dispositivo de Triangulação para indicar a direção do segundo ponto de triangulação. Assim que o encontrar, relate sua localização ao Mercador do Vento Tuluman, no Acampamento do Tuluman, logo depois da ponte que leva à ilha de Manaforja Ara, em Eternévoa."
Lang["Q1_10276"] = "Triângulo completo"
Lang["Q2_10276"] = "Recupere o Cristal Ata'mal e leve-o à Imagem do Príncipe do Nexus Haramad, no Pináculo da Tempestade, em Eternévoa."
Lang["Q1_10280"] = "Entrega especial para Shattrath"
Lang["Q2_10280"] = "Entregue o Cristal de Ata'mal a A'dal, no Terraço da Luz, em Shattrath."
Lang["Q1_10704"] = "Como entrar em Arcatraz"
Lang["Q2_10704"] = "A'dal quer que você recupere os fragmentos Superior e Inferior da Chave de Arcatraz. Leve-os para ele, para que ele possa criar a Chave para Arcatraz para você."
Lang["Q1_9824"] = "Perturbações arcanas"
Lang["Q2_9824"] = "Use o Cristal Violeta da Vidência perto de fontes subterrâneas de água no Porão do Senhorio e, depois, fale novamente com o Arquimago Alturus nos arredores de Karazhan."
Lang["Q1_9825"] = "Atividade incessante"
Lang["Q2_9825"] = "Leve 10 Essências Fantasmagóricas para o Arquimago Alturus nos arredores da torre de Karazhan."
Lang["Q1_9826"] = "Contato de Dalaran"
Lang["Q2_9826"] = "Leve o Relatório de Alturus para o Arquimago Cedric nos arredores de Dalaran."
Lang["Q1_9829"] = "Hadggar"
Lang["Q2_9829"] = "Entregue o Relatório de Alturus para Hadggar, em Shattrath, que fica na Mata Terokkar."
Lang["Q1_9831"] = "Entrando em Karazhan"
Lang["Q2_9831"] = "Hadggar quer que você entre no Labirinto Soturno em Auchindoun e recupere o Primeiro Fragmento de Chave de um Recipiente Arcano escondido lá."
Lang["Q1_9832"] = "O segundo e o terceiro fragmentos"
Lang["Q2_9832"] = "Obtenha o Segundo Fragmento de Chave de um Recipiente Arcano no Reservatório Presacurva, e o Terceiro Fragmento de Chave de um Recipiente Arcano na Bastilha da Tormenta. Fale novamente com Hadggar em Shattrath quando completar a tarefa."
Lang["Q1_9836"] = "O toque do mestre"
Lang["Q2_9836"] = "Vá até as Cavernas do Tempo e convença Medivh a habilitar a Chave Restaurada do Aprendiz."
Lang["Q1_9837"] = "Retorno a Hadggar"
Lang["Q2_9837"] = "Fale novamente com Hadggar em Shattrath e mostre a Chave do Mestre."
Lang["Q1_9838"] = "O Olho Violeta"
Lang["Q2_9838"] = "Fale com o Arquimago Alturus nos arredores de Karazhan."
Lang["Q1_9630"] = "O Diário de Medivh"
Lang["Q2_9630"] = "O Arquimago Alturus, na Trilha do Vento Morto, quer que você entre em Karazhan e fale com Wravien."
Lang["Q1_9638"] = "Em boas mãos"
Lang["Q2_9638"] = "Fale com Gradav na Biblioteca do Guardião, em Karazhan."
Lang["Q1_9639"] = "Kamsis"
Lang["Q2_9639"] = "Fale com Kamsis na Biblioteca do Guardião, em Karazhan."
Lang["Q1_9640"] = "O vulto de Aran"
Lang["Q2_9640"] = "Obtenha o Diário de Medivh e fale novamente com Kamsis na Biblioteca do Guardião, em Karazhan."
Lang["Q1_9645"] = "O Terraço do Mestre"
Lang["Q2_9645"] = "Vá até o Terraço do Mestre em Karazhan e leia o Diário de Medivh. Volte ao Arquimago Alturus com o Diário de Medivh depois de completar a tarefa."
Lang["Q1_9680"] = "Desencavando o passado"
Lang["Q2_9680"] = "O Arquimago Alturus quer que você vá até as montanhas ao sul de Karazhan, na Trilha do Vento Morto, e recupere um Fragmento de Osso Carbonizado."
Lang["Q1_9631"] = "Ajuda de uma colega"
Lang["Q2_9631"] = "Leve o Fragmento de Osso Carbonizado para Kalynna Lathred na Área 52, que fica em Eternévoa."
Lang["Q1_9637"] = "O pedido de Kalynna"
Lang["Q2_9637"] = "Kalynna Lathred quer que você recupere o Tomo de Crepúsculo do Grão-bruxo Maléter nos Salões Despedaçados, que ficam na Cidadela Fogo do Inferno, e também o Livro dos Nomes Esquecidos do Tecetrevas Syth nos Salões dos Sethekk, que ficam em Auchindoun.\n\nEssa missão deve ser completada no modo Heroico."
Lang["Q1_9644"] = "Nocturno"
Lang["Q2_9644"] = "Vá até o Terraço do Mestre em Karazhan e use a Urna de Kalynna para evocar Nocturno. Recupere a Essência Arcana Enfraquecida do cadáver de Nocturno e leve-a para o Arquimago Alturus."
Lang["Q1_10901"] = "A clava de Kar'desh"
Lang["Q2_10901"] = "Skar'this, o Herege, no Pátio dos Escravos do Reservatório Presacurva, quer que você leve o Sinete Terreno e o Sinete Fulgurante até ele."
Lang["Q1_10900"] = "A marca de Vashj"
Lang["Q2_10900"] = "Queime até o fim, <race>. Queime tudo! Elas não merecem nada! Está ouvindo? NADA! Elas têm de pagar pelo que fizeram. Pelo que continuam a fazer.\n\nEu mesmo mataria Vashj se conseguisse me libertar destas malditas barras.\n\nOu talvez você queira fazer o trabalho de Neptulon? A morte dela beneficia a nós dois, pele-macia. Você vai me ajudar a criar a clava sagrada."
Lang["Q1_10681"] = "A Mão de Gul'dan"
Lang["Q2_10681"] = "Fale com o Reparador da Terra Torlok no Altar da Danação, que fica no Vale da Lua Negra."
Lang["Q1_10458"] = "Espíritos do fogo e da terra enfurecidos"
Lang["Q2_10458"] = "O Reparador da Terra Torlok, no Altar da Danação do Vale da Lua Negra, quer que você use o Totem dos Espíritos para capturar 8 Almas da Terra e 8 Almas do Fogo."
Lang["Q1_10480"] = "Espíritos da água enfurecidos"
Lang["Q2_10480"] = "O Reparador da Terra Torlok, no Altar da Danação do Vale da Lua Negra, quer que você use o Totem dos Espíritos para capturar 5 Almas da Água."
Lang["Q1_10481"] = "Espíritos do ar enfurecidos"
Lang["Q2_10481"] = "O Reparador da Terra Torlok, no Altar da Danação do Vale da Lua Negra, quer que você use o Totem dos Espíritos para capturar 10 Almas do Ar."
Lang["Q1_10513"] = "Oronok Coração-partido"
Lang["Q2_10513"] = "Procure Oronok Coração-partido na Plataforma Estilhaçada, ao norte da Cisterna Serpentálios."
Lang["Q1_10514"] = "Eu fui muitas coisas..."
Lang["Q2_10514"] = "Oronok Coração-partido na Fazenda de Oronok, que fica no Vale da Lua Negra, quer que você recolha 10 Tubérculos Lua Negra no Platô Despedaçado.\n\nEle também quer o Apito de Javali de Oronok de volta quando você terminar."
Lang["Q1_10515"] = "Dê uma lição"
Lang["Q2_10515"] = "Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra, quer que você destrua 10 Ovos de Esfola-pedra Vorasga no Platô Despedaçado."
Lang["Q1_10519"] = "A Cifra da Danação: verdade e história"
Lang["Q2_10519"] = "Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra, quer que você escute a história dele. Fale com Oronok para começar a ouvir a história."
Lang["Q1_10521"] = "Grom'tor, filho de Oronok"
Lang["Q2_10521"] = "Encontre Grom'tor, filho de Oronok, no Pontal dos Serpentálios, no Vale da Lua Negra."
Lang["Q1_10527"] = "Ar'tor, filho de Oronok"
Lang["Q2_10527"] = "Encontre Ar'tor, Filho de Oronok, no Pontal Illidari no Vale da Lua Negra."
Lang["Q1_10546"] = "Borak, filho de Oronok"
Lang["Q2_10546"] = "Encontre Borak, Filho de Oronok, perto da Ponta do Eclipse, no Vale da Lua Negra."
Lang["Q1_10522"] = "A Cifra da Danação: a carga de Grom'tor"
Lang["Q2_10522"] = "Grom'tor, Filho de Oronok, no Pontal dos Serpentálios, no Vale da Lua Negra, quer que você recupere o Primeiro Fragmento da Cifra da Danação."
Lang["Q1_10528"] = "Prisões demoníacas de cristal"
Lang["Q2_10528"] = "Procure e mate a Rainha da Dor Gabrissa no Pontal Illidari. Em seguida, volte até o cadáver de Ar'tor, Filho de Oronok, com a Chave Cristalina."
Lang["Q1_10547"] = "De cardólatras e ovos..."
Lang["Q2_10547"] = "Borak, Filho de Oronok, junto à ponte ao norte da Ponta do Eclipse, quer que você encontre um Ovo Podre de Arakkoa. O ovo deve ser entregue a Tobias, o Come-lixo, em Shattrath, localizada no noroeste da Mata Terokkar."
Lang["Q1_10523"] = "A Cifra da Danação: primeiro fragmento recuperado"
Lang["Q2_10523"] = "Leve a Caixa-forte de Grom'tor para Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra."
Lang["Q1_10537"] = "Lohn'goron, arco dos Coração-partido"
Lang["Q2_10537"] = "O Espírito de Ar'tor, no Pontal Illidari do Vale da Lua Negra, quer que você recupere Lohn'goron, Arco dos Coração-partido, com um dos demônios da área."
Lang["Q1_10550"] = "O feixe de cardossangue"
Lang["Q2_10550"] = "Leve o Feixe de Cardossangue a Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra."
Lang["Q1_10540"] = "A Cifra da Danação: a missão de Ar'tor"
Lang["Q2_10540"] = "O Espírito de Ar'tor no Pontal Illidari, no Vale da Lua Negra, quer que você recupere o Segundo Fragmento da Cifra da Danação, que está em poder de Veneratus, o Muitos.\n\nCriaturas atacadas ou danificadas pelo Espírito de Caçador não fornecerão saque nem experiência."
Lang["Q1_10570"] = "Um cardólatra da pesada"
Lang["Q2_10570"] = "Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você recupere a Missiva de Tempesfúria."
Lang["Q1_10576"] = "O golpe Lua Negra"
Lang["Q2_10576"] = "Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você recupere 6 peças de Armadura Eclipsion."
Lang["Q1_10577"] = "O que Illidan quer, Illidan consegue..."
Lang["Q2_10577"] = "Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você entregue a Mensagem de Illidan ao Grão-comandante Ruusk na Ponta do Eclipse."
Lang["Q1_10578"] = "A Cifra da Danação: a missão de Borak"
Lang["Q2_10578"] = "Borak, Filho de Oronok, que está na ponte perto da Ponta do Eclipse, no Vale da Lua Negra, quer que você recupere o Terceiro Fragmento da Cifra da Danação com Ruul, o Obscurecente.\n\nNesta missão, será melhor ir em grupo."
Lang["Q1_10541"] = "A Cifra da Danação: segundo fragmento recuperado"
Lang["Q2_10541"] = "Leve a Arca de Ar'tor para Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra."
Lang["Q1_10579"] = "A Cifra da Danação: terceiro fragmento recuperado"
Lang["Q2_10579"] = "Leve o Cofre de Borak para Oronok Coração-partido na Fazenda de Oronok, no Vale da Lua Negra."
Lang["Q1_10588"] = "A Cifra da Danação"
Lang["Q2_10588"] = "Use a Cifra da Danação no Altar da Danação para evocar Cyrukh, o Senhor do Fogo.\n\nDestrua Cyrukh, o Senhor do Fogo, e então fale com o Reparador da Terra Torlok no Altar da Danação."
Lang["Q1_10883"] = "A Chave de Tormenta"
Lang["Q2_10883"] = "Fale com A'dal em Shattrath."
Lang["Q1_10884"] = "Prova dos naarus: misericórdia"
Lang["Q2_10884"] = "A'dal, em Shattrath, quer que você pegue o Machado não Usado do Carrasco nos Salões Despedaçados da Cidadela Fogo do Inferno.\n\nEsta missão deve ser completada em dificuldade heroica."
Lang["Q1_10885"] = "Prova dos naarus: força"
Lang["Q2_10885"] = "A'dal, em Shattrath, quer que você pegue o Tridente de Kalithresh e a Essência do Murmúrio.\n\nEsta missão deve ser completada em dificuldade heroica."
Lang["Q1_10886"] = "Prova dos naarus: tenacidade"
Lang["Q2_10886"] = "A'dal, em Shattrath, quer que você resgate Millhouse Manavento de Arcatraz, na Bastilha da Tormenta.\n\nEsta missão deve ser completada em dificuldade heroica."
Lang["Q1_10888"] = "Prova dos naarus: Magtheridon"
Lang["Q2_10888"] = "A'dal, na cidade de Shattrath, quer que você mate Magtheridon."
Lang["Q1_10680"] = "A Mão de Gul'dan"
Lang["Q2_10680"] = "Fale com o Reparador da Terra Torlok no Altar da Danação, que fica no Vale da Lua Negra."
Lang["Q1_10445"] = "As ampolas da eternidade"
Lang["Q2_10445"] = "Soridormi, nas Cavernas do Tempo, quer que você recupere o Resíduo da Ampola de Vashj da Dama Vashj no Reservatório Presacurva e o Resíduo da Ampola de Kael do Kael'thas Andassol na Bastilha da Tormenta."
Lang["Q1_10568"] = "Tabuletas de Baa'ri"
Lang["Q2_10568"] = "A Anacoreta Ceyla no Altar de Sha'tar quer que você colete 12 Tabuletas Baa'ri no chão e com os Trabalhadores Grislíngua nas Ruínas de Baa'ri.\n\nCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures."
Lang["Q1_10683"] = "Tabuletas de Baa'ri"
Lang["Q2_10683"] = "O Arcanista Thelis, no Sacrário Estelar, quer que você recolha 12 Tabuletas Baa'ri no chão e com os Trabalhadores Grislíngua, nas Ruínas de Baa'ri.\n\nCompletar missões para os Áugures reduzirá sua reputação com os Aldor."
Lang["Q1_10571"] = "Oronu, o Ancião"
Lang["Q2_10571"] = "A Anacoreta Ceyla no Altar de Sha'tar quer que você obtenha as Ordens de Akama que estão com Oronu, o Ancião, nas Ruínas de Baa'ri.\n\nCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures."
Lang["Q1_10684"] = "Oronu, o Ancião"
Lang["Q2_10684"] = "O Arcanista Thelis no Sacrário Estelar quer que você obtenha as Ordens de Akama com Oronu, o Ancião, nas Ruínas de Baa'ri.\n\nCompletar missões para os Áugures reduzirá sua reputação com os Aldor."
Lang["Q1_10574"] = "Os corruptores Grislíngua"
Lang["Q2_10574"] = "Obtenha os quatro fragmentos de medalhão com Haalum, Eykenen, Lakaan e Uylaru e procure a Anacoreta Ceyla no Altar de Sha'tar, que fica no Vale da Lua Negra.\n\nCompletar missões para os Aldor reduzirá sua reputação com os Áugures."
Lang["Q1_10685"] = "Os corruptores Grislíngua"
Lang["Q2_10685"] = "Obtenha os quatro fragmentos de medalhão com Haalum, Eykenen, Lakaan e Uylaru e procure o Arcanista Thelis no Sacrário Estelar, que fica no Vale da Lua Negra.\n\nCompletar missões para os Áugures reduzirá sua reputação entre os Aldor."
Lang["Q1_10575"] = "A Jaula do Carcereiro"
Lang["Q2_10575"] = "A Anacoreta Ceyla quer que você entre na Jaula do Carcereiro, ao sul das Ruínas de Baa'ri e interrogue Sanoru quanto à localização de Akama.\n\nCompletar missões para os Aldor reduzirá sua reputação junto aos Áugures."
Lang["Q1_10686"] = "A Jaula do Carcereiro"
Lang["Q2_10686"] = "O Arcanista Thelis quer que você entre na Jaula do Carcereiro, ao sul das Ruínas de Baa'ri e interrogue Sanoru quanto à localização de Akama.\n\nCompletar missões para os Áugures reduzirá sua reputação entre os Aldor."
Lang["Q1_10622"] = "Prova de fidelidade"
Lang["Q2_10622"] = "Mate Zandras na Jaula do Carcereiro, no Vale da Lua Negra, e fale novamente com Sanoru."
Lang["Q1_10628"] = "Akama"
Lang["Q2_10628"] = "Fale com Akama dentro da câmara oculta na Jaula do Carcereiro."
Lang["Q1_10705"] = "Vidente Udalo"
Lang["Q2_10705"] = "Encontre o Vidente Udalo em Arcatraz, na Bastilha da Tormenta."
Lang["Q1_10706"] = "Um portento misterioso"
Lang["Q2_10706"] = "Fale novamente com Akama na Jaula do Carcereiro no Vale da Lua Negra."
Lang["Q1_10707"] = "O Terraço de Ata'mal"
Lang["Q2_10707"] = "Chegue ao topo do Terraço de Ata'mal no Vale da Lua Negra e obtenha o Coração da Fúria. Cumprida a tarefa, fale novamente com Akama na Jaula do Carcereiro, que fica no Vale da Lua Negra."
Lang["Q1_10708"] = "A promessa de Akama"
Lang["Q2_10708"] = "Traga o Medalhão de Karabor a A'dal na cidade de Shattrath."
Lang["Q1_10944"] = "O segredo comprometido"
Lang["Q2_10944"] = "Vá até a Jaula do Carcereiro no Vale da Lua Negra e fale com Akama."
Lang["Q1_10946"] = "Ardil dos Grislíngua"
Lang["Q2_10946"] = "Vá à Bastilha da Tormenta e, vestindo o capucho dos Grislíngua, mate Al'ar. Fale novamente com Akama no Vale da Lua Negra quando concluir a tarefa."
Lang["Q1_10947"] = "Um artefato do passado"
Lang["Q2_10947"] = "Vá às Cavernas do Tempo em Tanaris e obtenha acesso à batalha de Monte Hyjal. Dentro da caverna, derrote Cólerus Hibernálgida e traga o Filactério Escalonado no Tempo até Akama no Vale da Lua Negra."
Lang["Q1_10948"] = "A alma cativa"
Lang["Q2_10948"] = "Vá até a cidade de Shattrath e informe a A'dal o pedido de Akama."
Lang["Q1_10949"] = "Entrada do Templo Negro"
Lang["Q2_10949"] = "Vá até a entrada do Templo Negro no Vale da Lua Negra e fale com Xi'ri."
Lang["Q1_10985"] = "Uma distração para Akama"
Lang["Q2_10985"] = "Akama e Maiev precisam entrar no Templo Negro no Vale da Lua Negra quando as forças de Xi'ri criarem a distração."
Lang["Q1_10984"] = "Fale com o ogro"
Lang["Q2_10984"] = "Fale com o Ogro Grok no Bairro Inferior em Shattrath."
Lang["Q1_10983"] = "Mog'dorg, o Rugoso"
Lang["Q2_10983"] = "Fale com Mog'dorg, o Rugoso, no topo de uma das torres do lado de fora do Círculo Sangrento, que fica nas Montanhas da Lâmina Afiada."
Lang["Q1_10995"] = "Grulloc tem dois crânios"
Lang["Q2_10995"] = "Recupere o Crânio de Dragão de Grulloc e entregue a Mog'dorg, o Rugoso, no alto da torre do Círculo Sangrento, nas Montanhas da Lâmina Afiada."
Lang["Q1_10996"] = "Baú do tesouro de Maggoc"
Lang["Q2_10996"] = "Recupere o Baú do Tesouro de Maggoc e entregue a Mog'dorg, o Rugoso, no alto da torre do Círculo Sangrento, nas Montanhas da Lâmina Afiada."
Lang["Q1_10997"] = "Gronn defende suas bandeiras"
Lang["Q2_10997"] = "Recupere o Estandarte de Slaag e entregue a Mog'dorg, o Rugoso, no alto da torre do Círculo Sangrento, nas Montanhas da Lâmina Afiada."
Lang["Q1_10998"] = "Negócios (gri)mortais"
Lang["Q2_10998"] = "Você tem que recuperar o Grimório Vil de Vim'gol e depois entregar a Mog'dorg, o Rugoso, no alto da torre do Círculo Sangrento, nas Montanhas da Lâmina Afiada."
Lang["Q1_11000"] = "Atrás do Trituralma"
Lang["Q2_11000"] = "Recupere a Alma de Skulloc e a entregue a Mog'dorg, o Rugoso, no alto da torre do Círculo Sangrento, nas Montanhas da Lâmina Afiada."
Lang["Q1_11022"] = "Fale com Mog'dorg"
Lang["Q2_11022"] = "Fale com Mog'dorg, o Rugoso. Ele fica no topo da torre no lado leste do Círculo Sangrento, que fica nas Montanhas da Lâmina Afiada."
Lang["Q1_11009"] = "Céu ôgrico"
Lang["Q2_11009"] = "Mog'dorg, o Rugoso, ordenou que fale com Chu'a'lor em Ogri'la, que fica nas Montanhas da Lâmina Afiada."
Lang["Q1_10804"] = "Bondade"
Lang["Q2_10804"] = "Mordenai, nos Campos da Asa Etérea, que fica no Vale da Lua Negra, quer que você alimente 8 Dracos Asa Etérea Adultos."
Lang["Q1_10811"] = "Procure Neltarako"
Lang["Q2_10811"] = "Procure Neltarako, patrono da Revoada Asa Etérea."
Lang["Q1_10814"] = "A história de Neltarako"
Lang["Q2_10814"] = "Fale com Neltarako e ouça a história dele."
Lang["Q1_10836"] = "Infiltrando-se na Fortaleza Presa do Dragão"
Lang["Q2_10836"] = "Neltarako, voando alto sobre os Campos da Asa Etérea no Vale da Lua Negra, quer que você mate 15 Orcs Presa do Dragão.\n\nQualquer orc da Presa do Dragão na Fortaleza Presa do Dragão servirá."
Lang["Q1_10837"] = "Para a Plataforma da Asa Etérea!"
Lang["Q2_10837"] = "Neltarako, voando alto sobre os Campos da Asa Etérea no Vale da Lua Negra, quer que você colete 12 Cristais Etervinha da Plataforma da Asa Etérea."
Lang["Q1_10854"] = "A força de Neltarako"
Lang["Q2_10854"] = "Neltarako, voando alto sobre os Campos da Asa Etérea no Vale da Lua Negra, quer que você liberte 5 Dracos Asa Etérea Escravizados."
Lang["Q1_10858"] = "Karynakhan"
Lang["Q2_10858"] = "Procure Karynakhan na Fortaleza Presa do Dragão."
Lang["Q1_10866"] = "Zuluhed, o Insano"
Lang["Q2_10866"] = "Mate Zuluhed, o Insano, recolha a Chave de Zuluhed e use-a nas Correntes de Zuluhed para libertar Karynakhan."
Lang["Q1_10870"] = "Aliados dos Asa Etérea"
Lang["Q2_10870"] = "Deixe Karynakhan levá-<lo/la> até Mordenai nos Campos da Asa Etérea."
Lang["Q1_3801"] = "Legado dos Ferro Negro"
Lang["Q2_3801"] = "Fale com Franclorn Forjífice se tiver interesse em obter uma chave para a parte principal da cidade."
Lang["Q1_3802"] = "Legado dos Ferro Negro"
Lang["Q2_3802"] = "Mate Fineous Forçanegra e recupere o grande martelo Ferrovil. Leve-o para o Santuário de Thaurissan e coloque-o na estátua de Franclorn Forjífice."
Lang["Q1_5096"] = "Distrações escarlate"
Lang["Q2_5096"] = "Vá até a base de operações da Cruzada Escarlate, que fica entre o Campo Pedravil e as Lágrimas de Dalson, e destrua a Tenda de Comando.\n\nPlante a bandeira do Flagelo no acampamento e fale novamente com o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais."
Lang["Q1_5098"] = "Você não vê as torres?"
Lang["Q2_5098"] = "Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la.\n\nDepois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais."
Lang["Q1_838"] = "Scolomântia"
Lang["Q2_838"] = "Fale com o Boticário Trépido no Baluarte das Terras Pestilentas Ocidentais."
Lang["Q1_964"] = "Fragmentos de Ossos"
Lang["Q2_964"] = "Leve 15 Fragmentos de Ossos para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5514"] = "Um molde que vale ouro"
Lang["Q2_5514"] = "Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan."
Lang["Q1_5802"] = "A forja do Pico Penacho de Fogo"
Lang["Q2_5802"] = "Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada.\n\nLeve a Chave-mestra Inacabada para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5804"] = "O escaravelho de Araj"
Lang["Q2_5804"] = "Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5511"] = "A chave para Scolomântia"
Lang["Q2_5511"] = "Pronto, aqui está: a Chave Esqueleto completa. Tenho toda a certeza de que esta chave vai permitir que você entre em Scolomântia."
Lang["Q1_5092"] = "Abrindo caminho"
Lang["Q2_5092"] = "Mate 10 Esfoladores Descarnados e 10 Carniçais Salivantes na Colina do Pesar.\n\nFale novamente com o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5097"] = "Você não vê as torres?"
Lang["Q2_5097"] = "Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la.\n\nDepois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5533"] = "Scolomântia"
Lang["Q2_5533"] = "Fale com o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5537"] = "Fragmentos de Ossos"
Lang["Q2_5537"] = "Leve 15 Fragmentos de Ossos para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5538"] = "Um molde que vale ouro"
Lang["Q2_5538"] = "Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan."
Lang["Q1_5801"] = "A forja do Pico Penacho de Fogo"
Lang["Q2_5801"] = "Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada.\n\nLeve a Chave-mestra Inacabada para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5803"] = "O escaravelho de Araj"
Lang["Q2_5803"] = "Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais."
Lang["Q1_5505"] = "A chave para Scolomântia"
Lang["Q2_5505"] = "Bem, <name>, aqui está: a chave-mestra completa. Tenho certeza absoluta de que essa chave vai permitir que você entre nos confins da Scolomântia. Mas só tem um jeito de saber se ela funciona. Meu conselho: nem perca tempo com testes.\n\nBoa sorte, grande herói. Que você continue a emanar luz na escuridão."
Lang["Q1_6804"] = "Água contaminada"
Lang["Q2_6804"] = "Use o Aspecto de Neptulon nos elementais contaminados das Terras Pestilentas Orientais. Leve 12 Braçadeiras Dissonantes e o Aspecto de Neptulon ao Duque Hidráxis em Azshara."
Lang["Q1_6805"] = "Tempestades e estrondores"
Lang["Q2_6805"] = "Mate 15 Tempestades de Poeira e 15 Estrondores do Deserto e fale novamente com o Duque Hidráxis em Azshara."
Lang["Q1_6821"] = "O Olho do Mirabrasa"
Lang["Q2_6821"] = "Leve o Olho do Mirabrasa ao Duque Hidráxis em Azshara."
Lang["Q1_6822"] = "O Núcleo Derretido"
Lang["Q2_6822"] = "Mate 1 Senhor do Fogo, 1 Gigante Derretido, 1 Cão-magma Antigo e 1 Irrompedor de Lava e depois fale novamente com o Duque Hidráxis em Azshara."
Lang["Q1_6823"] = "Agente de Hidráxis"
Lang["Q2_6823"] = "Alcance a reputação de <Honrado/Honrada> pelos Senhores das Águas Hidraxianos e depois fale com o Duque Hidráxis em Azshara."
Lang["Q1_6824"] = "Mãos do inimigo"
Lang["Q2_6824"] = "Leve as Mãos de Lúcifron, Sulfuron, Geena e Shazzrah ao Duque Hidráxis em Azshara."
Lang["Q1_7486"] = "Recompensa para um herói"
Lang["Q2_7486"] = "Obtenha a recompensa na Arca de Hidráxis."
Lang["Q1_5726"] = "Inimigos ocultos"
Lang["Q2_5726"] = "Leve uma Insígnia do Tenente para Thrall em Orgrimmar."
Lang["Q1_5727"] = "Inimigos ocultos"
Lang["Q2_5727"] = "Leve a Insígnia do Tenente para Neeru Cortafogo e fale com ele. Avalie se ele acredita que você é um membro da Lâmina Ardente e, depois, fale novamente com Thrall em Orgrimmar."
Lang["Q1_5728"] = "Inimigos ocultos"
Lang["Q2_5728"] = "Mate Bazzalan e Jergosh, o Invocador e fale novamente com Thrall em Orgrimmar."
Lang["Q1_5729"] = "Inimigos ocultos"
Lang["Q2_5729"] = "Fale com Neeru Cortafogo em Orgrimmar."
Lang["Q1_5730"] = "Inimigos ocultos"
Lang["Q2_5730"] = "Fale com Thrall em Orgrimmar e conte a ele o que você descobriu."
Lang["Q1_5722"] = "Em busca da algibeira perdida"
Lang["Q2_5722"] = "Investigue as Cavernas Ígneas em busca do corpo de Mauren Temível Totem e procure quaisquer itens de interesse."
Lang["Q1_5723"] = "Testando a força do inimigo"
Lang["Q2_5723"] = "Procure as Cavernas Ígneas em Orgrimmar e mate 8 Troggs Iraflama e 8 Xamãs Iraflama, depois fale novamente com Rahauro no Penhasco do Trovão."
Lang["Q1_5724"] = "Devolvendo a algibeira perdida"
Lang["Q2_5724"] = "Leve a Algibeira do Temível Totem para Rahauro no Penhasco do Trovão."
Lang["Q1_5725"] = "O poder de destruir..."
Lang["Q2_5725"] = "Leve os livros \"Feitiços da Sombra\" e \"Encantamentos do Éter\" para Varimatras na Cidade Baixa."
Lang["Q1_5761"] = "Mate a besta"
Lang["Q2_5761"] = "Entre nas Cavernas Ígneas e mate Taragaman, o Famélico, depois leve o coração dele para Neeru Cortafogo em Orgrimmar."
Lang["Q1_12"] = "A Milícia do Povo"
Lang["Q2_12"] = "Miguel Mantoforte quer que você mate 15 Coureadores Défias e 15 Contrabandistas Défias, e fale novamente com ele no Morro da Sentinela."
Lang["Q1_13"] = "A Milícia do Povo"
Lang["Q2_13"] = "Miguel Mantoforte quer que você mate 15 Pilhadores Défias e 15 Gatunos Défias, e fale novamente com ele no Morro da Sentinela."
Lang["Q1_14"] = "A Milícia do Povo"
Lang["Q2_14"] = "Miguel Mantoforte quer que você mate 15 Bandoleiros Défias, 5 Tocaiantes Défias e 5 Rufiões Défias, e fale novamente com ele no Morro da Sentinela."
Lang["Q1_65"] = "A Irmandade Défias"
Lang["Q2_65"] = "Miguel Mantoforte quer que você converse com Wiley, em Vila Plácida."
Lang["Q1_132"] = "A Irmandade Défias"
Lang["Q2_132"] = "Leve o Bilhete do Wiley para Miguel Mantoforte no Cerro Oeste."
Lang["Q1_135"] = "A Irmandade Défias"
Lang["Q2_135"] = "Leve o Bilhete do Wiley para Mathias Shaw em Ventobravo."
Lang["Q1_141"] = "A Irmandade Défias"
Lang["Q2_141"] = "Leve o Relatório do Shaw para Miguel Mantoforte no Cerro Oeste."
Lang["Q1_142"] = "A Irmandade Défias"
Lang["Q2_142"] = "Rastreie o Mensageiro Défias no Cerro Oeste e leve sua mensagem para Mantoforte."
Lang["Q1_155"] = "A Irmandade Défias"
Lang["Q2_155"] = "Escolte o Traidor Défias ao esconderijo secreto da Irmandade Défias. Quando o Traidor Défias mostrar onde VanCleef e seus comparsas estão escondidos, retorne a Miguel Mantoforte com a informação."
Lang["Q1_166"] = "A Irmandade Défias"
Lang["Q2_166"] = "Mate Edwin VanCleef e leve a cabeça dele para Miguel Mantoforte."
Lang["Q1_167"] = "Meu irmão..."
Lang["Q2_167"] = "Leve a Insígnia da Liga dos Exploradores do Encarregado Urtigão para Wilder Urtigão em Ventobravo."
Lang["Q1_168"] = "Lembranças dos que se foram"
Lang["Q2_168"] = "Recupere 4 Carteiras do Sindicato dos Mineradores e leve-as para Wilder Urtigão em Ventobravo."
Lang["Q1_214"] = "Bandana de seda vermelha"
Lang["Q2_214"] = "A Batedora Riell, da Torre do Morro da Sentinela, quer que você lhe traga 10 Bandanas de Seda Vermelha."
Lang["Q1_2040"] = "Ataque subterrâneo"
Lang["Q2_2040"] = "Recupere o Engrenotreco Gnomo das Minas Mortas e devolva a Shoni, a Shilenchiosa, em Ventobravo."
Lang["Q1_2041"] = "Fale com Shoni"
Lang["Q2_2041"] = "Fale com Shoni, a Shilenchiosa, em Ventobravo."
Lang["Q1_373"] = "Uma carta não enviada"
Lang["Q2_373"] = "Entregue a Carta para o Arquiteto da Cidade a Baros Aleixo em Ventobravo."
Lang["Q1_92742"] = "Testando os poços"
Lang["Q2_92742"] = "Use o Kit de Amostras de Água de Poço para coletar amostras dos poços no Sítio dos Jansen e na Fazenda dos Peçanha."
Lang["Q1_92744"] = "Guelras de Murloc"
Lang["Q2_92744"] = "Alba Belua quer que você colete 7 Guelras de Murloc da Praia Grande ao longo da costa de Cerro Oeste."
Lang["Q1_92745"] = "A situação das minas"
Lang["Q2_92745"] = "Mate 4 Escavadores Kobolds na Mina Veiojango e 6 Mineradores Pata Molhada na Pedreira Costa Dourada."
Lang["Q1_92747"] = "Espionagem no Arroio da Lua"
Lang["Q2_92747"] = "Colete 8 Suprimentos Industriais Suspeitos no Arroio da Lua."
Lang["Q1_92748"] = "Consulta explosiva"
Lang["Q2_92748"] = "Viaje até o Distrito dos Anões em Ventobravo e encontre uma engenheira que possa ajudar."
Lang["Q1_92749"] = "Um plano explosivo"
Lang["Q2_92749"] = "Obtenha 10 Dinamites Grosseiras por meio de criação, troca ou na casa de leilões, depois fale novamente com Lorien Grenagem no Distrito dos Anões em Ventobravo."
Lang["Q1_92750"] = "Detonação à distância"
Lang["Q2_92750"] = "Fale com alguém da Inteligência de Ventobravo sobre como obter um detonador remoto."
Lang["Q1_92751"] = "Detonação à distância"
Lang["Q2_92751"] = "Leve o Kit de Detonador Remoto para Lorien Grenagem no Distrito dos Anões de Ventobravo."
Lang["Q1_92752"] = "Consulta explosiva"
Lang["Q2_92752"] = "Retorne para Alba Belua em Cerro Oeste."
Lang["Q1_92753"] = "Destruição nas Minas Mortas"
Lang["Q2_92753"] = "Ache a forja escondida nas Minas Mortas e arme os Explosivos Extradestrutivos nas imediações dela. Depois, encontre Alba Belua na saída das Minas Mortas."
Lang["Q1_92819"] = "Destruição nas Minas Mortas"
Lang["Q2_92819"] = "Use o detonador."
Lang["N1_9196"] = "Grão-lorde Omokk"
Lang["N2_9196"] = "Grão-lorde Omokk é o primeiro chefe do Pico da Rocha Negra Inferior."
Lang["N1_9237"] = "Senhor da Guerra Voone"
Lang["N2_9237"] = "Senhor da Guerra Voone é um minichefe do Pico da Rocha Negra Inferior."
Lang["N1_9568"] = "Lorde Supremo Wyrmthalak"
Lang["N2_9568"] = "Lorde Supremo Wyrmthalak é o último chefe do Pico da Rocha Negra Inferior."
Lang["N1_10429"] = "Chefe Guerreiro Laceral Mão Negra"
Lang["N2_10429"] = "Chefe Guerreiro Laceral Mão Negra é o sexto chefe do Pico da Rocha Negra Superior. Dal'rend, mais conhecido como Rend, comandava a Horda Negra e era a maior ameaça a Thrall."
Lang["N1_10182"] = "Rexxar"
Lang["N2_10182"] = "<Campeão da Horda>\n\nAnda do sul da Cordilheira das Torres de Pedra até o norte de Feralas."
