Lang["N2_8197"] = "Chronalis, da Revoada Bronze.\n\nFica na entrada das Cavernas do Tempo."
Lang["N1_10664"] = "Áugure"
Lang["N2_10664"] = "Áugure, da Revoada Azul.\n\nFica no fundo da caverna de Mazthoril."
Lang["N1_12900"] = "Somnus"
Lang["N2_12900"] = "Somnus, da Revoada Verde.\n\nFica no lado leste do Templo Submerso."
Lang["N1_12899"] = "Axtroz"
Lang["N2_12899"] = "Axtroz, da Revoada Vermelha.\n\nFica em Grim Batol, Pantanal."
