Lang["Q1_2200"] = "De volta a Uldaman"
Lang["Q2_2200"] = "Procure pistas sobre disposição atual do colar de Didiê dentro de Uldaman. O paladino morto que ele mencionou foi a última pessoa a portá-lo."
Lang["Q1_2201"] = "Encontre as gemas"
Lang["Q2_2201"] = "Encontre o rubi, a safira e o topázio que foram espalhados por toda Uldaman. Uma vez adquiridos, entre em contato com Didiê Du Mocó remotamente, usando o Frasco de Vidência que ele lhe deu.\n\nDe acordo com o diário...\n* O rubi está escondido em uma área barricada de Umbraforja.\n* O topázio está escondido numa urna em uma das áreas dos troggs, perto dos anões da Aliança.\n\n* A safira foi reivindicada por Grimlok, o líder dos troggs."
Lang["Q1_2202"] = "Busca pelos reagentes de Uldaman"
