Lang["Q1_2339"] = "Encontre as Gemas e a Fonte de Energia"
Lang["Q2_2339"] = "Recupere todas as três gemas e uma fonte de energia para o colar de Uldaman e leve-as para Jarkal Limuno, em Karrath. Jarkal acredita que uma fonte de energia pode ser encontrada no constructo mais forte presente em Uldaman.\n\nDe acordo com o diário:\n* O rubi está escondido em uma área de Umbraforja protegida por barreiras.\n* O topázio está escondido numa urna em uma das áreas dos troggs, perto de alguns anões da Aliança.\n* A safira foi reclamada por Grimlok, o líder dos troggs."
