Lang["Q1_4001"] = "O que está acontecendo?"
Lang["Q2_4001"] = "Fale com Kharan Feromalho para obter informações sobre o sequestro da Princesa Moira Barbabronze. Leve as informações para Thrall em Orgrimmar.\n\nGor'shak mencionou que Kharan estava preso em uma cela próxima."
Lang["Q1_4002"] = "Os Reinos do Leste"
Lang["Q2_4002"] = "Fale com Thrall se estiver <preparado/preparada> para assumir a missão que ele planejou."
Lang["Q1_4003"] = "O resgate real"
Lang["Q2_4003"] = "Mate o Imperador Dagran Thaurissan e liberte a Princesa Moira Barbabronze do feitiço maligno."
Lang["Q1_4004"] = "A princesa foi resgatada?"
Lang["Q2_4004"] = "Fale novamente com Thrall!"
Lang["Q1_4022"] = "O gosto das chamas"
Lang["Q2_4022"] = "Mostre a Ciro Terepento a Muda de Pele da Revoada Negra que você recebeu de Kalaran Finalâmina."
Lang["Q1_4024"] = "O gosto das chamas"
Lang["Q2_4024"] = "Vá para o Abismo Rocha Negra e mate Bael'gar.\n\nA única coisa que você sabe é que o gigante mora no Abismo Rocha Negra. Lembre-se de usar a Muda de Pele Alterada da Revoada Negra nos restos mortais de Bael'gar para capturar a Essência Abrasadora.\n\nLeve a Essência Abrasadora Aprisionada para Ciro Terepento."
Lang["Q1_4063"] = "O levante das máquinas"
Lang["Q2_4063"] = "Encontre e mate Lorde Golem Argelmach. Leve a cabeça dele para Lotwil. Você também precisará coletar 10 Núcleos de Elemental Intactos dos Golens Rasgafúria e Constructos Armipotentes que protegem Argelmach. Você sabe disso porque é paranormal."
Lang["Q1_4081"] = "SE VIR, MATE: Anões Ferro Negro"
Lang["Q2_4081"] = "Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados!\n\nO Senhor da Guerra Trincador quer que você mate 15 Guardas Furiadastra, 10 Carcereiros Furiadastra e 5 Soldados Rasos Furiadastra. Fale novamente com ele quando o trabalho estiver terminado."
Lang["Q1_4082"] = "SE VIR, MATE: Oficiais Ferro Negro de Alta Patente"
Lang["Q2_4082"] = "Vá até o Abismo Rocha Negra e destrua aqueles invasores degenerados!\n\nO Senhor da Guerra Trincador quer que você mate 10 Socorristas Furiadastra, 10 Soldados Furiadastra e 10 Oficiais Furiadastra. Fale novamente com ele quando o trabalho for concluído."
Lang["Q1_4123"] = "O Coração da Montanha"
Lang["Q2_4123"] = "Leve o Coração da Montanha para Maxwort Uberraio nas Estepes Ardentes."
Lang["Q1_3701"] = "As fumegantes Ruínas de Thaurissan"
Lang["Q2_3701"] = "Vá até as Ruínas de Thaurissan, nas Estepes Ardentes, e descubra informações sobre as Relíquias de Thaurissan. Fale novamente com a Historiadora Real Arquefilis quando terminar."
Lang["Q1_3702"] = "As fumegantes Ruínas de Thaurissan"
Lang["Q2_3702"] = "Escute a Historiadora Real Arquefilis recontar a história de Thaurissan."
Lang["Q1_3911"] = "O último elemento"
Lang["Q2_3911"] = "Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais."
Lang["Q1_4126"] = "Hurley Bafonegro"
Lang["Q2_4126"] = "Leve a Receita Perdida de Cervaforte para Ragnar Cervaforte em Kharanos."
Lang["Q1_4128"] = "Ragnar Cervaforte"
Lang["Q2_4128"] = "Fale com Ragnar Cervaforte."
Lang["Q1_4134"] = "Receita Perdida de Cervaforte"
Lang["Q2_4134"] = "Leve a Receita Perdida de Cervaforte para Vivian Latumba em Karrath."
Lang["Q1_4136"] = "Ribas Parafuseta"
Lang["Q2_4136"] = "Leve a Cabeça do Ribas para Yuka Parafuseta nas Estepes Ardentes."
Lang["Q1_4201"] = "A poção do amor"
Lang["Q2_4201"] = "Leve 4 Sangues-de-grom, 10 Veios de Prata Gigantes e a Ampola da Nagmara Cheia para a Lady Nagmara no Abismo Rocha Negra."
Lang["Q1_4262"] = "Mestre Supremo Piro"
Lang["Q2_4262"] = "Mate o Mestre Supremo Piro e fale novamente com Jalinda Ramo.\n\nVocê se lembra de Jalinda ter dito que Piro guarda a pedreira. Que tal procurar por lá?"
Lang["Q1_4263"] = "Incendius!"
Lang["Q2_4263"] = "Encontre Lorde Incendius no Abismo Rocha Negra e destrua-o!"
Lang["Q1_4286"] = "Produto de primeira"
Lang["Q2_4286"] = "Viaje para o Abismo Rocha Negra e recupere 20 Pochetes Ferro Negro. Fale novamente com Oralius quando tiver completado a tarefa. Você supõe que os anões Ferro Negro de dentro do Abismo Rocha Negra carregam essa tal de \"pochete\"."
Lang["Q1_4341"] = "Kharan Feromalho"
Lang["Q2_4341"] = "Viaje para Abismo Rocha Negra e encontre Kharan Feromalho.\n\nO Rei mencionou que Kharan estava preso lá — talvez seja bom procurar uma prisão."
Lang["Q1_4342"] = "O conto de Kharan"
Lang["Q2_4342"] = "Ouça Kharan Feromalho contar a história dele."
Lang["Q1_4361"] = "Informante das más notícias"
Lang["Q2_4361"] = "Volte a Altaforja e dê as más notícias ao Rei Magni Barbabronze."
Lang["Q1_4362"] = "O destino do reino"
Lang["Q2_4362"] = "Volte ao Abismo Rocha Negra e resgate a Princesa Moira Barbabronze das garras malignas do Imperador Dagran Thaurissan."
Lang["Q1_4363"] = "A surpresa da Princesa"
Lang["Q2_4363"] = "Volte a Altaforja e fale com o Rei Magni Barbabronze."
Lang["Q1_7201"] = "O último elemento"
Lang["Q2_7201"] = "Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais."
Lang["Q1_5212"] = "A carne não mente"
Lang["Q2_5212"] = "Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne."
Lang["Q1_5213"] = "O agente ativo"
Lang["Q2_5213"] = "Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco."
Lang["Q1_5214"] = "A tentação de Fras Siabi"
Lang["Q2_5214"] = "Encontre a tabacaria de Fras Siabi em Stratholme e recolha uma caixa do Tabaco da Lata do Fras Siabi. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço."
Lang["Q1_5243"] = "Casas do sagrado"
Lang["Q2_5243"] = "Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente."
Lang["Q1_5251"] = "O arquivista"
Lang["Q2_5251"] = "Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate."
Lang["Q1_5262"] = "A verdade desaba sobre todos"
Lang["Q2_5262"] = "Leve a Cabeça do Balnazzar para o Duque Nicolau Zverenhoff nas Terras Pestilentas Orientais."
Lang["Q1_5263"] = "Acima e além"
Lang["Q2_5263"] = "Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff."
Lang["Q1_5281"] = "As almas inquietas"
Lang["Q2_5281"] = "Encontre Egan. Ele foi visto pela última vez nos arredores de Stratholme."
Lang["Q1_5282"] = "As almas inquietas"
Lang["Q2_5282"] = "Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade!\n\nLiberte 15 Almas Inquietas, depois fale novamente com Egan."
Lang["Q1_5961"] = "O campeão da Rainha Banshees"
Lang["Q2_5961"] = "Fale com Nathanos, o Arauto da Praga nas Terras Pestilentas Orientais. Dizem que ele fixou residência no Sítio dos Marris."
Lang["Q1_6022"] = "Matar com propósito"
Lang["Q2_6022"] = "Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada."
Lang["Q1_6042"] = "Pequenos transtornos da Morte-em-Vida"
Lang["Q2_6042"] = "Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado."
Lang["Q1_6133"] = "A mando do lorde patrulheiro"
Lang["Q2_6133"] = "Vá à fronteira norte das Terras Pestilentas Orientais e recupere os Arquivos de Quel'Thalas em algum lugar do Abrigo Quel'Lithien.\n\nVocê também precisa matar 8 Patrulheiros, 8 Trilheiros e 8 Mateiros."
Lang["Q1_6135"] = "Ah, Quiroscuro, como vos odeio..."
Lang["Q2_6135"] = "Encontre Quiroscuro e mate-o. Do cadáver, extraia um Tufo de Pele de Quiroscuro e leve para Nathanos Arauto da Praga.\n\nDizem que Quiroscuro vaga pelo campo ao norte do Sítio dos Marris."
Lang["Q1_6136"] = "O corpulento"
Lang["Q2_6136"] = "Encontre Brocassangre nos ermos do norte das Terras Pestilentas e destrua-o. Fale novamente com Nathanos Arauto da Praga quando tiver cumprido a missão."
Lang["Q1_6144"] = "Chamado ao comando"
Lang["Q2_6144"] = "Vá à Cidade Baixa e fale com Varimatras."
Lang["Q1_6163"] = "Ramstein"
Lang["Q2_6163"] = "Vá a Stratholme e mate Ramstein, o Devorador. Leve a cabeça dele como souvenir para Nathanos."
Lang["Q1_5341"] = "A fortuna da família Barov"
Lang["Q2_5341"] = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa."
Lang["Q1_5342"] = "O último Barov"
Lang["Q2_5342"] = "Vá para o Acampamento Ventogelante, no território da Aliança, e assassine Weldon Barov. Recolha a cabeça dele e fale novamente com Alexei Barov.\n\nEsteja avisad<o/a>: Weldon provavelmente estará muito bem protegido pela escória da Aliança."
Lang["Q1_5343"] = "A fortuna da família Barov"
Lang["Q2_5343"] = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, a Escritura de Montalvo, a Escritura da Serraria Tarren e a Escritura de Costa Sul. Fale novamente com Weldon Barov quando tiver terminado a tarefa."
Lang["Q1_5344"] = "O último Barov"
Lang["Q2_5344"] = "Vá para o Baluarte, no território da Horda, e assassine Alexei Barov. Recolha a cabeça dele e fale novamente com Weldon Barov.\n\nEsteja avisad<o/a>: Alexei provavelmente estará muito bem protegido pela escória da Horda."
Lang["Q1_5382"] = "Doutor Theolen Krastinov, o Carniceiro"
Lang["Q2_5382"] = "Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa."
Lang["Q1_5384"] = "Kirtonos, o Arauto"
Lang["Q2_5384"] = "Volte a Scolomântia com o Sangue dos Inocentes em mãos. Encontre a varanda e derrame o Sangue dos Inocentes no braseiro. Kirtonos virá na intenção de devorar sua alma.\n\nLute com bravura, não dê nenhuma brecha! Destrua Kirtonos e fale novamente com Eva Sarkhoff."
Lang["Q1_5125"] = "O ajuste de contas de Aurius"
Lang["Q2_5125"] = "<name>, estou morrendo... mas minha alma está salva. Não tenho nem palavras para dizer o quanto devo a você. Por favor, leve isto consigo. Continue lutando, valente <class>!"
Lang["Q1_5461"] = "Ras Friomúrmuro, o humano"
Lang["Q2_5461"] = "Viaje para o Planalto Arathi, até as ruínas de Stromgarde. Vasculhe Stromgarde em busca de um Livro de Recordações. Se encontrar o item, retorne com ele até o Magistrado Marduque."
Lang["Q1_5462"] = "Ras Friomúrmuro, o moribundo"
Lang["Q2_5462"] = "Viaje para a Capela Esperança da Luz, nas Terras Pestilentas Orientais, e procure por Leonid Bartolomeu, o Venerado. Mostre a ele o Livro de Recordações e conte tudo o que descobriu."
Lang["Q1_5463"] = "Dádiva de Menethil"
Lang["Q2_5463"] = "Vá até Stratholme e encontre a Dádiva de Menethil. Ponha o Livro de Recordações no solo profanado."
Lang["Q1_5466"] = "Ras Friomúrmuro, o lich"
Lang["Q2_5466"] = "Procure por Ras Friomúrmuro em Scolomântia. Quando o encontrar, use a Lembrança Vinculada em sua versão morto-vivo. Quando conseguir transformá-lo novamente em mortal, mate-o e recupere a Cabeça Humana de Ras Friomúrmuro. Leve a cabeça de volta ao Magistrado Marduque."
Lang["Q1_5515"] = "Saco de Horrores de Krastinov"
Lang["Q2_5515"] = "Localize Janice Barov em Scolomântia e a destrua. Recupere o Saco de Horrores de Krastinov do cadáver dela. Entregue o saco a Eva Sarkhoff."
Lang["Q1_5526"] = "Pedaços de Vinhavil"
Lang["Q2_5526"] = "Encontre a Vinhavil no Gládio Cruel e obtenha uma lasca dela. É bem provável que você só consiga encontrar uma depois da derrota de Azzin, o Selvamorfo. Use o Relicário da Pureza para selar a lasca com segurança e leve-a de volta para Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua."
Lang["Q1_5529"] = "Filhotes Pestilentos"
Lang["Q2_5529"] = "Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz."
Lang["Q1_5582"] = "Escama de dragão saudável"
Lang["Q1_5522"] = "Leonid Bartolomeu"
Lang["Q2_5522"] = "Leve os Ovos Congelados para Leonid Bartolomeu, nas Terras Pestilentas Orientais."
Lang["Q1_5531"] = "Betina Bigozinco"
Lang["Q2_5531"] = "Leve os Ovos Congelados para Betina Bigozinco."
Lang["Q1_4771"] = "Aposta da Aurora"
Lang["Q2_4771"] = "Coloque a Aposta da Aurora na Sala de Exibição de Scolomântia. Derrote Vectus, depois fale novamente com Betina Bigozinco."
Lang["Q2_5582"] = "Leve a Escama de Dragão Saudável para Betina Bigozinco na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais."
Lang["Q1_5742"] = "Redenção"
Lang["Q2_5742"] = "Escute o que Tirion Fordring tem a dizer."
Lang["Q1_5781"] = "Elixir de memórias esquecidas"
Lang["Q2_5781"] = "Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo."
Lang["Q1_5845"] = "Da honra perdida"
Lang["Q2_5845"] = "Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo."
Lang["Q1_5846"] = "Do amor e da família"
Lang["Q2_5846"] = "Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura."
Lang["Q1_5848"] = "Do amor e da família"
Lang["Q2_5848"] = "Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo.\n\nLeve a pintura de volta para Tirion Fordring."
Lang["Q1_6141"] = "Irmão Anton"
Lang["Q2_6141"] = "Fale com o Irmão Anton na Desolação."
Lang["Q1_6521"] = "Uma aliança profana"
Lang["Q2_6521"] = "Leve a cabeça do Embaixador Malcin para Varimatras, na Cidade Baixa."
Lang["Q1_6522"] = "Uma aliança profana"
Lang["Q2_6522"] = "Leve o Pergaminho Pequeno para Varimatras, na Cidade Baixa."
Lang["Q1_6561"] = "Vilania das Profundezas"
Lang["Q2_6561"] = "Leve a cabeça do Senhor do Crepúsculo Kelris para Bashana Runa Totem, no Penhasco do Trovão."
Lang["Q1_6922"] = "O Barão Aquanis"
Lang["Q2_6922"] = "Leve o Globo d'Água Estranho para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris."
Lang["Q1_78917"] = "Âmago do caos"
Lang["Q2_78917"] = "Leve a Pérola das Profundezas Negras para Bashana Runa Totem no Penhasco do Trovão."
Lang["Q1_80140"] = "Ficar ou não ficar... eis a questão!"
Lang["Q2_80140"] = "Você pode ficar com o anel ou achar a pessoa que faz a gravação no interior dele."
Lang["Q1_80325"] = "O rei louco"
Lang["Q2_80325"] = "Leve as Anotações de Engenharia de Termaplugue para o Nogg no Vale da Honra, em Orgrimmar."
Lang["Q1_6562"] = "Problemas nas Profundezas"
Lang["Q2_6562"] = "Fale com Je'neu Sancrea no Vale Gris."
Lang["Q1_6563"] = "A essência de Aku'mai"
Lang["Q2_6563"] = "Entregue 20 Safiras de Aku'Mai a Je'neu Sancrea no Vale Gris."
Lang["Q1_6564"] = "Lealdade aos Deuses Antigos"
Lang["Q2_6564"] = "Leve o Bilhete Úmido para Je'neu Sancrea, no Vale Gris."
Lang["Q1_6565"] = "Lealdade aos Deuses Antigos"
Lang["Q2_6565"] = "Mate Lorgus Jett nas Profundezas Negras e depois fale novamente com Je'neu Sancrea no Vale Gris."
Lang["Q1_6626"] = "A hoste do mal"
Lang["Q2_6626"] = "Mate 8 Guerreiros do Urzal, 8 Tecespinhos do Urzal e 8 Sectários da Cabeça da Morte, depois fale novamente com Mírian Lunacanto perto da entrada do Urzal dos Mortos."
Lang["Q1_6921"] = "Nas ruínas"
Lang["Q2_6921"] = "Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris."
Lang["Q1_6981"] = "A lasca faiscante"
Lang["Q2_6981"] = "Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante.\n\nDepois, entregue a lasca conforme as orientações."
Lang["Q1_7028"] = "Raízes do mal"
Lang["Q2_7028"] = "Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação."
Lang["Q1_7029"] = "A corrupção de Torpelíngua"
Lang["Q2_7029"] = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.\n\nUse a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.\n\nCure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra."
Lang["Q1_7041"] = "A corrupção de Torpelíngua"
Lang["Q2_7041"] = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.\n\nUse a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir.\n\nCure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Talendria, no Posto do Nijel."
Lang["Q1_7044"] = "Lendas de Maraudon"
Lang["Q2_7044"] = "Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras.\n\nEncontre um jeito de falar com Celebras."
Lang["Q1_7046"] = "O Cetro de Celebras"
Lang["Q2_7046"] = "Ajude Celebras, o Redimido, a criar o Cetro de Celebras.\n\nFale com ele quando o ritual estiver concluído."
Lang["Q1_7064"] = "Corrupção da terra e dos grãos"
Lang["Q2_7064"] = "Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação."
Lang["Q1_7065"] = "Corrupção da terra e dos grãos"
Lang["Q2_7065"] = "Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação."
Lang["Q1_7066"] = "A semente da vida"
Lang["Q2_7066"] = "Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida."
Lang["Q1_7067"] = "As instruções do pária"
Lang["Q2_7067"] = "Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação."
Lang["Q1_7068"] = "Fragmentos de lascanegra"
Lang["Q2_7068"] = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar."
Lang["Q1_7070"] = "Fragmentos de lascanegra"
Lang["Q2_7070"] = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso."
Lang["Q1_7441"] = "Pusillin e o Ancião Azj'Tordin"
Lang["Q2_7441"] = "Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin.\n\nFale novamente com Azj'Tordin no Pavilhão Lariss, em Feralas, caso você recupere o Livro de Encantamentos."
Lang["Q1_7461"] = "A loucura intrínseca"
Lang["Q2_7461"] = "Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará.\n\nDestrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu.\n\nFale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão."
Lang["Q1_7462"] = "O tesouro de Shen'dralar"
Lang["Q2_7462"] = "Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Reclame sua recompensa!"
Lang["Q1_7481"] = "Lendas élficas"
Lang["Q2_7481"] = "Procure Kariel Winthalus em Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você possa encontrar."
Lang["Q1_7482"] = "Lendas élficas"
Lang["Q2_7482"] = "Procure Kariel Winthalus em Gládio Cruel. Reporte-se, então, à Erudita Runacardos em Plumaluna com qualquer informação que você encontrar."
Lang["Q1_7488"] = "A teia de Letendris"
Lang["Q2_7488"] = "Leve a Teia de Letendris para Latrônicus Lunalança no Domínio de Plumaluna, em Feralas."
Lang["Q1_7489"] = "A teia de Letendris"
Lang["Q2_7489"] = "Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas."
Lang["Q1_7492"] = "Aldeia Mojache"
Lang["Q2_7492"] = "Fale com Talo Casco de Espinhos na Aldeia Mojache, em Feralas."
Lang["Q1_7494"] = "Domínio de Plumaluna"
