Lang["Q1_4701"] = "Acabando com ela"
Lang["Q2_4701"] = "Vá ao Pico da Rocha Negra e destrua a fonte da ameaça worg. Quando você deixou Helendis, ele gritou um nome: Halycon. É assim que os orcs se referem aos worgs."
Lang["Q1_4724"] = "Senhora do matilha"
Lang["Q2_4724"] = "Mate Halycon, senhora da matilha dos Worgs Machado Sangrento."
Lang["Q1_4729"] = "Mascotes exóticas do Kibler"
Lang["Q2_4729"] = "Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler."
Lang["Q1_4734"] = "Congelar os ovos"
Lang["Q2_4734"] = "Use o Protótipo de Ovosciloscópio em um ovo no Viveiro."
Lang["Q1_4735"] = "Coleção de ovos"
Lang["Q2_4735"] = "Leve 8 Ovos de Dragão Recolhidos e o Módulo Colectrônico a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes."
Lang["Q1_4742"] = "Selo da Ascensão"
Lang["Q2_4742"] = "Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan.\n\nOs generais, como informado a você por Vaelan, são: Senhor da Guerra Voone dos Fumocardo, Grão-lorde Omokk dos Agulhapétrea e Lorde Supremo Wyrmthalak dos Machado Sangrento."
Lang["Q1_4743"] = "Selo da Ascensão"
Lang["Q2_4743"] = "Vá para o Pântano da Serpe, que fica no Pântano Vadeoso. Encontre o draco ancião Ardeluta e ataque-o sem misericórdia até que sua vontade seja quebrada.\n\nÉ nesse momento que você deve colocar o Selo da Ascensão de Metal Bruto em frente a essa fera imponente. Você deve então ser <rápido/rápida> para usar o Orbe de Energia Dracônica em sua forma enfraquecida e dominar suas faculdades mentais. Controle a fera e lance as chamas da Revoada Dragônica Negra sobre o Selo da Ascensão de Metal Bruto!"
Lang["Q1_4764"] = "Broche do Finitudo"
