Lang["Q1_4866"] = "Leite materno"
Lang["Q2_4866"] = "No coração do Pico da Rocha Negra você vai encontrar a Mãe Queimateia. Chame a atenção dela e deixe-a envenenar você. É bem provável que você precise matá-la também. Fale novamente com João Roto depois que for envenenad<o/a> para que ele possa \"ordenhar\" você."
