Lang["Q1_7636"] = "Báculo dos Antigos"
Lang["Q2_7636"] = "Você precisa encontrar e destruir aqueles quatro corruptores demoníacos:\n\nSimone, a Sedutora.\n\nKlinfran, o Enlouquecido.\n\nSolenor, o Matador.\n\nArtórius, o Destruidor.\n\nDestrua aquelas criaturas e fale novamente com Vartrus, o Anciente, na Selva Maleva, trazendo as cabeças deles.\n\nConsulte a Casca Petrificada no seu inventário para ter pistas da localização deles.\n\nVocê TEM QUE completar a tarefa sozinh<o/a>."
