Lang["Q1_1641"] = "Tomo de Divindade"
Lang["Q2_1641"] = "Aqui em Ventobravo, eu sou responsável por botar os paladinos na trilha da virtude maior enquanto eles se dedicam à Luz e à defesa de Azeroth do Flagelo e qualquer ameaça.\n\nChegou a hora de você dar o primeiro passo rumo à verdadeira virtude. Se aceitar, eu darei a você o Livro de Divindade. Por meio do estudo dele, você aprenderá sobre a Luz e sobre o que se espera de você. Se for capaz de entender o que ele ensina e tiver a força necessária, você poderá obter habilidades ainda mais poderosas."
