Lang["Q1_1651"] = "Tomo da Bravura"
Lang["Q2_1651"] = "Proteja Dafne Calmafonte do ataque dos Défias.\n\nPara obter êxito, seus espíritos não podem ser despidos do lodo mortal.\n\nQuando você conseguir, fale novamente com Dafne Calmafonte."
