Lang["Q1_1442"] = "Em busca da Gema Kor"
Lang["Q2_1442"] = "Leve a Gema Kor para Trovejius Tecevento, na Costa Negra."
Lang["Q1_1654"] = "A prova da retidão"
Lang["Q2_1654"] = "Usando as Anotações do Jardel sobre Armas, encontre Madeira de Carvalho de Pedralva, o Carregamento de Minério Refinado do Bailor, o Martelo de Ferreiro de Jardel e uma Gema Kor. Depois, entregue tudo a Jardel Calmafonte em Altaforja."
Lang["Q1_1806"] = "A prova da retidão"
Lang["Q2_1806"] = "Espere que Jardel Calmafonte termine de forjar uma arma para você."
Lang["Q1_1794"] = "Tomo da Bravura"
Lang["Q2_1794"] = "Tomo da Bravura"
Lang["Q1_1793"] = "Tomo da Bravura"
Lang["Q2_1793"] = "Já está comprovado que a Luz é convosco, <name>. Contudo, conforme nosso tempo se torna mais e mais perigoso, torna-se importante conhecer a força que jaz sob a carne. Quando demônios, dragões ou qualquer outro mal puser os pés em nossas terras, seu estofo será testado. Mas será que você terá a força necessária?\n\nA bravura independentemente da situação é parte do que significa ser um <class>, tanto quanto a Luz, sua armadura ou sua arma. Proteger os fracos e não perder a fé são duas lições que você precisa aprender ao estudar aqui na Catedral da Luz."
