Lang["Q2_7638"] = "Fale com o Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."
Lang["Q1_7637"] = "Ênfase em sacrifício"
Lang["Q2_7637"] = "Viaje para Altaforja e obtenha o Incensório de Exorcismo do Sumo Sacerdote Rohan. Você precisará fazer uma doação de 150 moedas de ouro para obtê-lo."
Lang["Q1_7639"] = "O devido julgamento"
Lang["Q2_7639"] = "Leve o Incensório de Exorcismo para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."
Lang["Q1_7640"] = "Exorcizando a Várzea do Medo"
Lang["Q2_7640"] = "Use o Incensório de Exorcismo para expulsar os espíritos que atormentam a Várzea do Medo. Quando você tiver eliminado 25 Espíritos da Várzea do Medo, fale novamente com Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."
Lang["Q1_7641"] = "O trabalho de Grimand Elmore"
Lang["Q2_7641"] = "Fale com Grimand Elmore em Ventobravo no Distrito dos Anões de Ventobravo."
Lang["Q1_7642"] = "Coleta de produtos"
Lang["Q2_7642"] = "Leve 40 Runatramas, 6 Barras de Arcanita, 10 Lágrimas-de-arthas, 5 ampolas de Água Benta de Stratholme e 150 moedas de ouro para Grimand Elmore, no Distrito dos Anões de Ventobravo."
Lang["Q1_7643"] = "O Espírito Equino Antigo"
Lang["Q2_7643"] = "Obtenha uma ração de cavalo especial para alimentar o cavalo espiritual. Aparentemente, Judite Castanheira, que vive na Costa Sul, é a fornecedora da tal ração.\n\nEntre na masmorra de Gládio Cruel, em Feralas, e mate Gavíneo Lenhatorta. Isso libertará o Espírito Equino Antigo. Alimente-o com a ração de cavalo especial, o que acalmará o espírito. Finalmente, dê-lhe a Barda de Arcanita para que ele a abençoe."
Lang["Q1_7648"] = "O melhor trabalho de Grimand"
Lang["Q2_7648"] = "Leve a Barda de Arcanita para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo para que ele a inspecione."
Lang["Q1_7644"] = "Barda de Arcanita Abençoada"
Lang["Q2_7644"] = "Leve a Barda de Arcanita Abençoada para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."
Lang["Q1_7645"] = "Ração de Cavalo Enriquecida com Mana"
Lang["Q2_7645"] = "Obtenha 20 Biscoitos de Maná Enriquecido — o ingrediente chave para fazer Ração de Cavalo Enriquecida com Mana — para Judite Castanheira da Costa Sul, no Contraforte de Eira dos Montes. A Aurora Argêntea é conhecida como a única fornecedora dos biscoitos.\n\nVocê também precisa dar a ela 50 moedas de ouro para a apaziguar os ânimos dela."
Lang["Q1_7646"] = "O Cristal Divinatório"
Lang["Q2_7646"] = "Leve um Diamante Azerotiano e um Diamante Preto Límpido para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."
Lang["Q1_7647"] = "Julgamento e redenção"
Lang["Q2_7647"] = "Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará julgar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o e reclame a alma perdida do corcel caído.\n\nEntregue a Alma Redimida do Corcel e a Barda Encantada Abençoada ao Corcel Caído de Noctilatrus."
