Lang["Q1_2381"] = "Saqueando os saqueadores"
Lang["Q2_2381"] = "Leve o Tesouro dos Mares do Sul para Wrenix, o Ignóbil, na Vila Catraca. Não se esqueça de pegar um B.E.C.A. e as Ferramentas de Ladrões no Aparato Mercadotrônico do Wrenix. Você precisará desses dois itens para cumprir a missão.\n\nCaso seja atacado por papagaios nada amigáveis, use o B.E.C.A!"
