Lang["Q1_2460"] = "A saudação dos Mão Despedaçada"
Lang["Q2_2460"] = "Faça a Continência dos Mãos Despedaçada para Shenthul."
Lang["Q1_2458"] = "Missão secreta"
Lang["Q2_2458"] = "Vá à Torre da Empreendimentos S.A., ao norte do Charco de Lodo, e entre em contato com o agente secreto da Mão Despedaçada, o Capataz Arruela.\n\nQuando a torre estiver à vista, use o Sinalizador para anunciar sua chegada ao Capataz Arruela. Dispare DUAS vezes, depois aproxime-se do Capataz e faça a /continencia dos Mão Despedaçada.\n\nEstas ações devem ser executadas na ordem correta, já que Arruela vai atacar e eliminar qualquer pessoa que não reconheça."
Lang["Q1_2478"] = "Missão: possível, mas não provável"
Lang["Q2_2478"] = "Roube a Chave da Torre do Capataz Biela e, em seguida, mate 2 Peões Mutantes da Empreendimentos S.A., 2 Patrulheiros da Empreendimentos S.A. e 2 Vigias da Empreendimentos S.A.\n\nArranque a cabeça do Capataz-chefe Gallywix, arrombe o cofre dele e roube o Esconderijo do Preparado Adulterado do Zanzil. Leve-o junto com a cabeça para Shenthul em Orgrimmar para receber mais instruções."
Lang["Q1_2479"] = "A ajuda de Hinoto"
Lang["Q2_2479"] = "Vá até a Serraria Tarren, que fica no Contraforte de Eira dos Montes, e entregue a Amostra do Preparado de Zanzil a Serguei Hinoto.\n\nPara chegar à Serraria Tarren, pegue o Zepelim até a Cidade Baixa e siga a estrada em direção ao sul além de Pinhaprata, rumo à Eira dos Montes. É só seguir as placas!"
Lang["Q1_2480"] = "A ajuda de Hinoto"
Lang["Q2_2480"] = "Espere Serguei Hinoto concluir a cura."
Lang["Q1_2360"] = "Mathias e os Défias"
