Lang["Q1_2359"] = "Torre do Filipe"
Lang["Q2_2359"] = "Roube a chave, entre na Torre Défias e descubra o que tem dentro do Baú da Floresta do Crepúsculo. Leve todas as informações que coletar para Mathias Shaw em Ventobravo. Consulte o Diário de Marta se quiser mais detalhes sobre a torre."
Lang["Q1_2607"] = "O toque de Zanzil"
