Lang["Q2_2608"] = "Você precisa /deitar para ser <examinado/examinada> pelo Doutor Mixilpixil. Como é que ele vai descobrir a cura se não puder identificar a causa do problema?"
Lang["Q1_2609"] = "O toque de Zanzil"
