Lang["Q1_7602"] = "Essência Vil Impecável"
Lang["Q2_7602"] = "Leve três Essências Vis Impecáveis, originárias de três locais distintos, para Diabretim na Selva Maleva.\n\nOs Sátiros Legashi de Azshara possuem a Essência Vil Impecável da região deles, assim como os Legionários de Jaedenar e as Sentinelas Guardas Vis da Barreira do Inferno.\n\nBusque as Essências Vis Impecáveis e leve-as para Diabretim, na Selva Maleva."
Lang["Q1_7603"] = "Núcleo Infernal de Kroshius"
Lang["Q2_7603"] = "Procure os restos mortais de Kroshius no Vale das Escaras Pungentes, que fica na Selva Maleva. Ao encontrá-los, use o Fogo Vil perto deles e aguarde o retorno de Kroshius. Quando o infernal acordar, mate-o e retire do corpo dele o Núcleo Infernal de Kroshius.\n\nLeve o Núcleo para Niby, o Todo-poderoso na Selva Maleva."
