local f = CreateFrame("Frame")
f:RegisterEvent("ADDON_LOADED")
f:SetScript("OnEvent", function(self, _, nome)
	if nome ~= "FTAttune" then return end
	self:UnregisterEvent("ADDON_LOADED")
	local g = FTAttune_Data and FTAttune_Data.questGivers
	if not g then return end
	for q, n in pairs(dadores) do
		if g[q] then g[q][4] = n end
	end
end)
end
setfenv(Component, FT.attuneEnv)
Component(...)
